$_MODULE['<{layerslider}prestashop>_c878cdf0cb53e7dbeb791eab13b84146'] = 'Autoriser le redémarrage des diapositives lors du redimensionnement'; // Allow restarting slides on resize
$_MODULE['<{layerslider}prestashop>_0296ddaa31acdc8e379a3de8412aff9a'] = 'Certaines options de transformation et de transition ne peuvent pas être mises à jour à la volée lorsque la taille du navigateur ou l\'orientation de l\'appareil change. En activant cette option, le slider détectera automatiquement de telles situations et se redémarrera pour préserver son apparence.'; // Certain transformation and transition options cannot be updated on the fly when the browser size or device orientation changes. By enabling this option, the slider will automatically detect such situations and will restart the itself to preserve its appearance.
$_MODULE['<{layerslider}prestashop>_d9f1451d7e147a9d76732b903c85fd98'] = 'Utiliser l\'attribut srcset'; // Use srcset attribute
$_MODULE['<{layerslider}prestashop>_d962a6678a6f57c0697bdba39433e0d7'] = 'L\'attribut srcset permet de charger des images mises à l\'échelle dynamiquement en fonction de la résolution de l\'écran. Il peut économiser de la bande passante et permettre l\'utilisation d\'images prêtes pour la rétine sur les appareils à haute résolution. Dans de rares cas, cette option peut provoquer des images floues.'; // The srcset attribute allows loading dynamically scaled images based on screen resolution. It can save bandwidth and allow using retina-ready images on high resolution devices. In some rare edge cases, this option might cause blurry images.
$_MODULE['<{layerslider}prestashop>_806790e901a729799c42f26b23c5470f'] = 'Chargement différé amélioré'; // Enhanced lazy load
$_MODULE['<{layerslider}prestashop>_bb477d8d7ee0d5561c80c51482d44904'] = 'Le comportement de chargement différé par défaut fait un compromis pour assurer une compatibilité maximale tout en offrant une solution qui fonctionne idéalement dans presque tous les cas. Cependant, en laissant l\'attribut ’src’ de l\'image intact, il y a une légère chance que le navigateur commence à télécharger certains actifs pendant une fraction de seconde avant que Creative Slider ne les annule. L\'activation de cette option éliminera toute chance de générer même une quantité minuscule de trafic indésirable, mais elle peut aussi causer des problèmes pour l\'indexation par les moteurs de recherche et d\'autres thèmes/modules.'; // The default lazy loading behavior makes a compromise to ensure maximum compatibility while offering a solution that works ideally in almost all cases. However, by leaving the image ’src’ attribute untouched, there is a slight chance that the browser might start downloading some assets for a split second before Creative Slider cancels them. Enabling this option will eliminate any chance of generating even a minuscule amount of unwanted traffic, but it can also cause issues for search engine indexing and other themes/modules.
$_MODULE['<{layerslider}prestashop>_451af3f11142c7626d839eb7674d3e0a'] = 'Préférer le mode de fusion'; // Prefer Blend Mode
$_MODULE['<{layerslider}prestashop>_6da524b45307ee7baa37799db0cd4796'] = 'Activez cette option pour éviter les problèmes de mode de fusion avec les transitions de diapositives. En raison de limitations techniques, cela découpera également vos transitions de diapositives quels que soient vos paramètres.'; // Enable this option to avoid blend mode issues with slide transitions. Due to technical limitations, this will also clip your slide transitions regardless of your settings.
$_MODULE['<{layerslider}prestashop>_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Activé'; // Enabled
$_MODULE['<{layerslider}prestashop>_5e1575919121f7253b56bb39b99e1042'] = 'VotreLogo'; // YourLogo
$_MODULE['<{layerslider}prestashop>_367a210257e2ea49914c4a695f8abf70'] = 'Un calque d\'image fixe peut être affiché au-dessus du slider et reste immobile tout au long du slider. Peut être utilisé pour afficher des logos ou des filigranes.'; // A fixed image layer can be shown above the slider that remains still throughout the whole slider. Can be used to display logos or watermarks.
$_MODULE['<{layerslider}prestashop>_77c34b7517dd216292658ee3b420dd1f'] = 'Style de VotreLogo'; // YourLogo style
$_MODULE['<{layerslider}prestashop>_355a12e47302b7e2627dc90d1c0e79c6'] = 'Propriétés CSS pour contrôler le placement et l\'apparence de l\'image.'; // CSS properties to control the image placement and appearance.
$_MODULE['<{layerslider}prestashop>_1cfb56506d3621c27196a6aa02a23c39'] = 'Lien de VotreLogo'; // YourLogo link
$_MODULE['<{layerslider}prestashop>_7966bee26ee8f49f0c5693a3b25a3461'] = 'Entrez une URL pour lier l\'image VotreLogo.'; // Enter a URL to link the YourLogo image.
$_MODULE['<{layerslider}prestashop>_5afb14c537c0ed4ed3805e8f9c12ae68'] = 'Cible du lien'; // Link target
$_MODULE['<{layerslider}prestashop>_61c717e4d8c25d8ea4fe003f88675e74'] = 'Ouvrir dans la même page'; // Open on the same page
$_MODULE['<{layerslider}prestashop>_98a0075b23373e991f18c15fb8442d8b'] = 'Ouvrir dans une nouvelle page'; // Open on new page
$_MODULE['<{layerslider}prestashop>_67c48b3d90f5ae44e816fe1030452fb3'] = 'Ouvrir dans le cadre parent'; // Open in parent frame
$_MODULE['<{layerslider}prestashop>_e106bc3e705b4e24fe60a249e11c6f01'] = 'Ouvrir dans le cadre principal'; // Open in main frame
$_MODULE['<{layerslider}prestashop>_b77006f2d0398fa7e68ef1a893ef850c'] = 'ID de l\'article'; // Post ID
$_MODULE['<{layerslider}prestashop>_e4d99041f9e5af92b38767d09947600e'] = 'Titre de l\'article'; // Post Title
$_MODULE['<{layerslider}prestashop>_b5e6d43af159d5d593ca7c4b6db55491'] = 'Nombre de commentaires'; // Number of Comments
$_MODULE['<{layerslider}prestashop>_cf3fb1ff52ea1eed3347ac5401ee7f0c'] = 'Ascendant'; // Ascending
$_MODULE['<{layerslider}prestashop>_e3cf5ac19407b1a62c6fccaff675a53b'] = 'Descendant'; // Descending
$_MODULE['<{layerslider}prestashop>_1a3cb622f5613168ed16ba4ffcfe49fe'] = 'Définir une image de diapositive'; // Set a slide image
$_MODULE['<{layerslider}prestashop>_1cf966e0716f7f365751df6e4a86f43f'] = 'L\'image/arrière-plan de la diapositive. Cliquez sur l\'image pour ouvrir le gestionnaire d\'images afin de choisir ou de télécharger une image.'; // The slide image/background. Click on the image to open the Image Manager to choose or upload an image.
$_MODULE['<{layerslider}prestashop>_6f6cb72d544962fa333e2e34ce64f719'] = 'Taille'; // Size
$_MODULE['<{layerslider}prestashop>_13eac5a039bc8041315fe1165a245a98'] = 'La taille de l\'image de fond de la diapositive. Laissez cette option sur "hériter" si vous souhaitez la définir globalement depuis les Paramètres du Slider.'; // The size of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_c49484faf79e2388b580e49444d6ac11'] = 'Hériter'; // Inherit
$_MODULE['<{layerslider}prestashop>_52f5e0bc3859bc5f5e25130b6c7e8881'] = 'Position'; // Position
$_MODULE['<{layerslider}prestashop>_25824be059f35ecadb2d38a895f7e710'] = 'La position de l\'image de fond de la diapositive. Laissez cette option sur "hériter" si vous souhaitez la définir globalement depuis les Paramètres du Slider.'; // The position of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_cb5feb1b7314637725a2e73bdc9f7295'] = 'Couleur'; // Color
$_MODULE['<{layerslider}prestashop>_9880a2532d7550cb4bef6c24ce2275f3'] = 'La couleur de fond de la diapositive. Vous pouvez utiliser des noms de couleur, des valeurs hexadécimales, RGB ou RGBA.'; // The slide background color. You can use color names, hexadecimal, RGB or RGBA values.
$_MODULE['<{layerslider}prestashop>_9d8cfafeba857023956c26437b6570fc'] = 'Définir une vignette de diapositive'; // Set a slide thumbnail
$_MODULE['<{layerslider}prestashop>_b95232d8c69a9f62cd6dab61887acf0f'] = 'L\'image miniature de cette diapositive. Cliquez sur l\'image pour ouvrir le gestionnaire d\'images afin de choisir ou télécharger une image. Si vous laissez ce champ vide, l\'image de la diapositive sera utilisée.'; // The thumbnail image of this slide. Click on the image to open the Image Manager to choose or upload an image. If you leave this field empty, the slide image will be used.
$_MODULE['<{layerslider}prestashop>_e02d2ae03de9d493df2b6b2d2813d302'] = 'Durée'; // Duration
$_MODULE['<{layerslider}prestashop>_b0c71ca949422ff07096787e513bf3dc'] = 'Ici, vous pouvez définir l\'intervalle de temps entre les changements de diapositives, cette diapositive restera visible pendant le temps spécifié ici. Cette valeur est en millisecondes, donc la valeur 1000 signifie 1 seconde. Veuillez ne pas utiliser 0 ou des valeurs très faibles.'; // Here you can set the time interval between slide changes, this slide will stay visible for the time specified here. This value is in millisecs, so the value 1000 means 1 second. Please don't use 0 or very low values.
$_MODULE['<{layerslider}prestashop>_4357cfb0b7acc1db400c94094794ae17'] = 'Nous avons créé nos transitions de diapositives prédéfinies avec un soin particulier pour s\'adapter à la plupart des cas d\'utilisation. Cependant, si vous souhaitez augmenter ou diminuer la vitesse de ces transitions, vous pouvez outrepasser leur synchronisation ici en fournissant votre propre durée de transition en millisecondes. (1 seconde = 1000 millisecondes)'; // We've made our pre-defined slide transitions with special care to fit in most use cases. However, if you would like to increase or decrease the speed of these transitions, you can override their timing here by providing your own transition length in milliseconds. (1 second = 1000 milliseconds)
$_MODULE['<{layerslider}prestashop>_38912a644194123a9ee9d01e126fcfae'] = 'durée personnalisée'; // custom duration
$_MODULE['<{layerslider}prestashop>_1605a4f4a4e45503d3ac914de9fba80a'] = 'Décalage temporel'; // Time Shift
$_MODULE['<{layerslider}prestashop>_6d106138f5fadb601a337fca4d4b7a2e'] = 'Vous pouvez décaler le point de départ de la chronologie de l\'animation de la diapositive, de sorte que les calques puissent s\'animer plus tôt après un changement de diapositive. Cette valeur est en millisecondes. Une seconde équivaut à 1000 millisecondes. Vous ne pouvez utiliser qu\'une valeur négative.'; // You can shift the starting point of the slide animation timeline, so layers can animate in an earlier time after a slide change. This value is in milliseconds. A second is 1000 milliseconds. You can only use a negative value.
$_MODULE['<{layerslider}prestashop>_e1f70f4a4265cb51c1b219aa60eaa441'] = 'Entrer l\'URL'; // Enter URL
$_MODULE['<{layerslider}prestashop>_cfdb83fef5ccd56abb3592f98391b355'] = 'Si vous voulez lier toute la diapositive, tapez l\'URL ici. Vous pouvez choisir l\'une des options prédéfinies dans la liste déroulante lorsque vous cliquez dans ce champ. Vous pouvez également taper un croisillon suivi d\'un numéro pour lier ce calque à une autre diapositive. Exemple : #3 - cela passera à la troisième diapositive.'; // If you want to link the whole slide, type the URL here. You can choose one of the pre-defined options from the dropdown list when you click into this field. You can also type a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_1f7412ef1f7fdba3cc269af9a0b7a40c'] = 'Cible du lien'; // Link Target
$_MODULE['<{layerslider}prestashop>_e82688575274fd1ba522f5044431cc93'] = 'Faire défiler jusqu\'à l\'élément (Entrer le sélecteur)'; // Scroll to element (Enter selector)
$_MODULE['<{layerslider}prestashop>_1fc71d8275be86e2787bc4a8f0d62c84'] = 'Choisissez si le lien de la diapositive doit être au-dessus ou en dessous de vos calques. Cette dernière option rend le lien cliquable uniquement dans les espaces vides où l\'arrière-plan de la diapositive est visible, et vous permet de lier à la fois les diapositives et les calques indépendamment les uns des autres.'; // Choose whether the slide link should be on top or underneath your layers. The later option makes the link clickable only at empty spaces where the slide background is visible, and enables you to link both slides and layers independently from each other.
$_MODULE['<{layerslider}prestashop>_7e04fe64ab136e31d62fcc6ea113f1ca'] = 'Au-dessus des calques'; // On top of layers
$_MODULE['<{layerslider}prestashop>_d722a275a3f48eb46d892c9df863e1af'] = 'En dessous des calques'; // Underneath layers
$_MODULE['<{layerslider}prestashop>_739cea2b85156183f917f2ccaa10a50c'] = '#ID'; // #ID
$_MODULE['<{layerslider}prestashop>_06f695600f91bfbd579d9d8f5a0147bd'] = 'Vous pouvez appliquer un attribut ID à l\'élément HTML de cette diapositive pour l\'utiliser dans votre code CSS ou Javascript personnalisé.'; // You can apply an ID attribute on the HTML element of this slide to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_550dc007dba485adc22eddfe0af40a81'] = 'Lien profond'; // Deeplink
$_MODULE['<{layerslider}prestashop>_070cb374111546db9ae4642406963ebd'] = 'Vous pouvez spécifier un nom d\'alias de diapositive que vous pouvez utiliser dans vos URL avec un croisillon, de sorte que Creative Slider commencera avec la diapositive correspondante.'; // You can specify a slide alias name which you can use in your URLs with a hash mark, so Creative Slider will start with the correspondig slide.
$_MODULE['<{layerslider}prestashop>_436e4906cf91bb911a38eb161e858a69'] = 'Survol global'; // Global Hover
$_MODULE['<{layerslider}prestashop>_f22bc2f96ed30d26a29060598c44c2fa'] = 'En activant cette option, tous les calques déclencheront leurs transitions de survol en même temps lorsque vous survolez le slider avec le curseur de votre souris. C\'est utile pour créer des effets spectaculaires qui impliquent plusieurs transitions de calques et qui s\'activent au survol du slider au lieu de calques individuels.'; // By turning this option on, all layers will trigger their Hover Transitions at the same time when you hover over the slider with your mouse cursor. It’s useful to create spectacular effects that involve multiple layer transitions and activate on hovering over the slider instead of individual layers.
$_MODULE['<{layerslider}prestashop>_7acdf85c69cc3c5305456a293524386e'] = 'Caché'; // Hidden
$_MODULE['<{layerslider}prestashop>_a494a9272210a3aa3682f9fa8b6ad9fc'] = 'Si vous ne voulez pas utiliser cette diapositive sur votre page d\'accueil, mais que vous voulez la conserver, vous pouvez la cacher avec ce bouton.'; // If you don't want to use this slide in your front-page, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_d33fd48027b557f5bcb3f15a238d7537'] = 'Déborder les calques'; // Overflow layers
$_MODULE['<{layerslider}prestashop>_5bbae9c02b64de11da4d22707a297710'] = 'Par défaut, le slider découpe les calques en dehors de ses limites. Activez cette option pour autoriser le contenu qui déborde.'; // By default the slider clips the layers outside of its bounds. Enable this option to allow overflowing content.
$_MODULE['<{layerslider}prestashop>_57ffe7327fb6fb004c59466a978c4100'] = 'Commence le'; // Start on
$_MODULE['<{layerslider}prestashop>_6ba9104be4da1fea318c02faca91dad6'] = 'La diapositive planifiée ne sera visible pour vos visiteurs qu\'entre la période que vous définissez ici.<br>Nous utilisons le format international de date et d\'heure pour éviter toute ambiguïté.'; // Scheduled slide will only be visible to your visitors between the time period you set here.<br>We're using international date and time format to avoid ambiguity.
$_MODULE['<{layerslider}prestashop>_6ea6d7b483daeb9be3acaad212b04181'] = 'S\'arrête le'; // Stop on
$_MODULE['<{layerslider}prestashop>_b78a3223503896721cca1303f776159b'] = 'Titre'; // Title
$_MODULE['<{layerslider}prestashop>_a2e92861b757ab878312dd57993d60cf'] = 'Alt'; // Alt
$_MODULE['<{layerslider}prestashop>_f17b29e841d3183298a453dc423242a0'] = 'Nommez ou décrivez votre image de diapositive, afin que les moteurs de recherche et les logiciels de lecture d\'écran puissent l\'identifier correctement.'; // Name or describe your slide image, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_4252b72e6ebcd4d4b4c2e46a786f03d2'] = 'Zoom'; // Zoom
$_MODULE['<{layerslider}prestashop>_f5ca4abce85e2dddb0342d0bae3a7270'] = 'Zoom avant'; // Zoom In
$_MODULE['<{layerslider}prestashop>_30850b501f98539b1aabaa29fabe41ef'] = 'Zoom arrière'; // Zoom Out
$_MODULE['<{layerslider}prestashop>_8d2de5368588552fbae54044ac5c7b3d'] = 'Rotation'; // Rotate
$_MODULE['<{layerslider}prestashop>_8aa2fa2e684ba408f551f3504c47427e'] = 'La quantité de rotation (le cas échéant) en degrés utilisée dans l\'effet Ken Burns. Les valeurs négatives sont autorisées pour une rotation antihoraire.'; // The amount of rotation (if any) in degrees used in the Ken Burns effect. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_85a7cd587d6142dbfc1a4de05af7b75d'] = 'Échelle'; // Scale
$_MODULE['<{layerslider}prestashop>_2ed8e1d37be922f23b2713c3e69a85ae'] = 'Augmentez ou diminuez la taille de l\'image de fond de la diapositive dans l\'effet Ken Burns. La valeur par défaut est 1, la valeur 2 doublera l\'image, tandis que 0.5 donnera la moitié de la taille. Les valeurs négatives retourneront l\'image.'; // Increase or decrease the size of the slide background image in the Ken Burns effect. The default value is 1, the value 2 will double the image, while 0.5 results half the size. Negative values will flip the image.
$_MODULE['<{layerslider}prestashop>_a1fa27779242b4902f7ae3bdd5c6d508'] = 'Type'; // Type
$_MODULE['<{layerslider}prestashop>_4a2d97fd5296d09fea3cbe45d107a7b3'] = 'La valeur par défaut pour les calques en parallaxe sur cette diapositive, qu\'ils hériteront, sauf si vous le définissez autrement sur les calques concernés.'; // The default value for parallax layers on this slide, which they will inherit, unless you set it otherwise on the affected layers.
$_MODULE['<{layerslider}prestashop>_8c94134f25efe7680f9743b2774e8e1f'] = '2D'; // 2D
$_MODULE['<{layerslider}prestashop>_76aa96369abbba52e621bfa83da8e64f'] = '3D'; // 3D
$_MODULE['<{layerslider}prestashop>_a4ecfc70574394990cf17bd83df499f7'] = 'Événement'; // Event
$_MODULE['<{layerslider}prestashop>_87932092d26d18e63889036bbf70518e'] = 'Vous pouvez déclencher l\'effet de parallaxe soit en faisant défiler la page, soit en déplaçant le curseur de votre souris / en inclinant votre appareil mobile. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_58af070b9f7f3dc090af0ece708e8869'] = 'Curseur ou Inclinaison'; // Cursor or Tilt
$_MODULE['<{layerslider}prestashop>_61ca8fa7a7c8b4699523bc8773c306d0'] = 'Axes'; // Axes
$_MODULE['<{layerslider}prestashop>_fc888362a84b5b975136bbca8e1fc5c6'] = 'Choisissez sur quels axes les calques en parallaxe doivent se déplacer. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Choose on which axes parallax layers should move. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_6adf97f83acf6453d4a6a4b1070f3754'] = 'Aucun'; // None
$_MODULE['<{layerslider}prestashop>_2c452204ed58a6f4a3bcda80344b338a'] = 'Les deux axes'; // Both axes
$_MODULE['<{layerslider}prestashop>_ad09aaae9c9ffe403ffdb2a6568f5a36'] = 'Horizontal seulement'; // Horizontal only
$_MODULE['<{layerslider}prestashop>_354908b89248f3dcbab970b32860a331'] = 'Vertical seulement'; // Vertical only
$_MODULE['<{layerslider}prestashop>_8b622b0a6ecf4e0116eaf248876f8700'] = 'Origine de la transformation'; // Transform Origin
$_MODULE['<{layerslider}prestashop>_e5a904ff73268b65730e4fb8b6127bf1'] = 'Définit un point sur le canevas à partir duquel les transformations sont calculées. Par exemple, un calque peut pivoter autour de son axe central ou d\'un point entièrement personnalisé, comme l\'un de ses coins. Les trois valeurs représentent les axes X, Y et Z dans l\'espace 3D. Outre les valeurs en pixels et en pourcentage, vous pouvez également utiliser les constantes suivantes : top, right, bottom, left, center.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center.
$_MODULE['<{layerslider}prestashop>_97289d779de759c4fe3a0ef9d3a4ff3d'] = 'Durée du mouvement'; // Move duration
$_MODULE['<{layerslider}prestashop>_ef82e470cae5696da7dc47e9a50fa8f7'] = 'Contrôle la vitesse d\'animation des calques lorsque vous déplacez le curseur de votre souris ou inclinez votre appareil mobile. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0bdd8970e06688e4a6ad694b8ed7b9f7'] = 'Durée de sortie'; // Leave duration
$_MODULE['<{layerslider}prestashop>_9aa9b8945ad7ff74e04fb53dbbe3d1f2'] = 'Contrôle la rapidité avec laquelle vos calques reviennent à leur position d\'origine lorsque vous déplacez le curseur de votre souris en dehors d\'un slider en parallaxe. Cette valeur est en millisecondes. 1 seconde = 1000 millisecondes. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Controls how quickly your layers revert to their original position when you move your mouse cursor outside of a parallax slider. This value is in milliseconds. 1 second = 1000 milliseconds. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0aa6f4210bf373c95eda00232e93cd98'] = 'Distance'; // Distance
$_MODULE['<{layerslider}prestashop>_396950a091a406fcd6f9f4cc75927536'] = 'Augmentez ou diminuez l\'amplitude du mouvement des calques lorsque vous déplacez votre curseur de souris ou inclinez un appareil mobile. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_f1a42bd417390fc63b030a519624607a'] = 'Rotation'; // Rotation
$_MODULE['<{layerslider}prestashop>_331ee65576c7333ba77a13d691219105'] = 'Augmentez ou diminuez la quantité de rotation des calques dans l\'espace 3D lorsque vous déplacez votre curseur de souris ou inclinez un appareil mobile. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_a80420eef88d11f77532f1b9cb467fa3'] = 'Perspective'; // Perspective
$_MODULE['<{layerslider}prestashop>_7ba7448042bdf18c7669bec909a0a7be'] = 'Modifie la perspective des calques dans l\'espace 3D. C\'est la valeur par défaut sur cette diapositive, que les calques en parallaxe hériteront, sauf si vous le définissez autrement directement sur eux.'; // Changes the perspective of layers in the 3D space. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_d6432a4413208eee54d613ceb82f726a'] = 'Filtre de départ'; // Filter From
$_MODULE['<{layerslider}prestashop>_bd3ec381eecf6eb78c9a97594745d33c'] = 'Les filtres permettent d\'appliquer des effets comme le flou ou le changement de couleur à vos calques. Cliquez dans le champ de texte pour voir une sélection de filtres que vous pouvez utiliser. Bien que cliquer sur les options prédéfinies réinitialise le champ de texte, vous pouvez appliquer plusieurs filtres simplement en fournissant une liste séparée par des espaces de tous les filtres que vous souhaitez utiliser.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use.
$_MODULE['<{layerslider}prestashop>_6b770358764a885d6dc7f2be20604356'] = 'Filtre de fin'; // Filter To
$_MODULE['<{layerslider}prestashop>_05b1dc77590105a18fc4c02526fe0c7a'] = 'Lecture auto'; // Autoplay
$_MODULE['<{layerslider}prestashop>_2b3de50de6ab7bd0aaf46ae654032790'] = 'Afficher infos'; // Show Info
$_MODULE['<{layerslider}prestashop>_24b6472fcfa59cddd3f7bbc326582b5f'] = 'Contrôles'; // Controls
$_MODULE['<{layerslider}prestashop>_58bccbc47e6de6783fb90fd62890a171'] = 'Mode de remplissage'; // Fill mode
$_MODULE['<{layerslider}prestashop>_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Volume'; // Volume
$_MODULE['<{layerslider}prestashop>_56a7f02a3b02e4a16864670ff48745e1'] = 'Utiliser cette vidéo comme arrière-plan de diapositive'; // Use this video as slide background
$_MODULE['<{layerslider}prestashop>_4ee3787bc7df95d25272524868e60d4d'] = 'Force ce calque à agir comme l\'arrière-plan de la diapositive en couvrant tout le slider et en ignorant certaines transitions. Assurez-vous de fournir votre propre image de poster avec l\'option ci-dessus, afin que le slider puisse l\'afficher immédiatement au chargement de la page.'; // Forces this layer to act like the slide background by covering the whole slider and ignoring some transitions. Please make sure to provide your own poster image with the option above, so the slider can display it immediately on page load.
$_MODULE['<{layerslider}prestashop>_9d16dd63ee0afa947dc998fb3d5a4a96'] = 'Choisissez une image de superposition :'; // Choose an overlay image:
$_MODULE['<{layerslider}prestashop>_e13b4cc51565c9030f943e31c253c8aa'] = 'Recouvrez vos vidéos d\'une image de superposition pour y avoir des effets de points ou de rayures.'; // Cover your videos with an overlay image to have dotted or striped effects on them.
$_MODULE['<{layerslider}prestashop>_1529fb44e04df26ff7666faa9f58c605'] = 'DécalageX'; // OffsetX
$_MODULE['<{layerslider}prestashop>_0d12fb40782d7877c5018ff4b501e701'] = 'Décale la position de départ du calque de son original sur l\'axe horizontal du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'left\' ou \'right\' positionnent le calque hors de la zone de préparation, de sorte qu\'il entre en scène de chaque côté lors de l\'animation vers son emplacement de destination.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it enters the scene from either side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_1508a7d829d65cf5e117fdc2aca0f155'] = 'DécalageY'; // OffsetY
$_MODULE['<{layerslider}prestashop>_c91f704c049f7d06fe50106d7452c21c'] = 'Décale la position de départ du calque de son original sur l\'axe vertical du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la hauteur de ce calque. Les valeurs \'top\' ou \'bottom\' positionnent le calque hors de la zone de préparation, de sorte qu\'il entre en scène de chaque côté vertical lors de l\'animation vers son emplacement de destination.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it enters the scene from either vertical side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_7686cf30c00c9f146a9224a33ba99a0f'] = 'La durée de la transition en millisecondes lorsque le calque entre en scène. Une seconde équivaut à 1000 millisecondes.'; // The length of the transition in milliseconds when the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_f2572c86c0aff2b2b7a92fbb6dee1491'] = 'Commence à'; // Start at
$_MODULE['<{layerslider}prestashop>_1f413844a6a15351c7a32a16ce962bfd'] = 'Retarde la transition de la quantité de millisecondes donnée avant que le calque n\'entre en scène. Une seconde équivaut à 1000 millisecondes.'; // Delays the transition with the given amount of milliseconds before the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_32485d52ad7aea25b3bc80d416e76a3b'] = 'Accélération'; // Easing
$_MODULE['<{layerslider}prestashop>_ca9a3cf0ea2e65cd611fe23633cd1186'] = 'La fonction de synchronisation de l\'animation. Avec cette fonction, vous pouvez manipuler le mouvement de l\'objet animé. Veuillez cliquer sur le lien à côté de ce champ de sélection pour ouvrir easings.net pour plus d\'informations et des exemples en temps réel.'; // The timing function of the animation. With this function you can manipulate the movement of the animated object. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_04e0385c10aefee8e4681617d2f3ef40'] = 'Fondu'; // Fade
$_MODULE['<{layerslider}prestashop>_ecdc93d174113fe69b7cbf2c42b5a1cb'] = 'Faire un fondu du calque pendant la transition.'; // Fade the layer during the transition.
$_MODULE['<{layerslider}prestashop>_b98c4145f7f66383ce71bf31bc4850b2'] = 'Fait pivoter le calque du nombre de degrés donné. Les valeurs négatives sont autorisées pour une rotation antihoraire.'; // Rotates the layer by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_801e0dd823542f625e0f2ee135efb62d'] = 'RotationX'; // RotateX
$_MODULE['<{layerslider}prestashop>_54f64742da0d7bd157ccaf54d4ac73a1'] = 'Fait pivoter le calque le long de l\'axe X (horizontal) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Rotates the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_ea0928ab345567847020e1544892fba0'] = 'RotationY'; // RotateY
$_MODULE['<{layerslider}prestashop>_209eea8f9d8a60293098e07e8951e156'] = 'Fait pivoter le calque le long de l\'axe Y (vertical) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Rotates the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_5a013b463ee01be2924568775fdddfb1'] = 'InclinaisonX'; // SkewX
$_MODULE['<{layerslider}prestashop>_253108f96bfad9912bb2178a4c7aef73'] = 'Incline le calque le long de l\'axe X (horizontal) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Skews the layer along the X (horizontal) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_eeb66258f8bf4bb3c0763461b5c1797d'] = 'InclinaisonY'; // SkewY
$_MODULE['<{layerslider}prestashop>_9d19b1698a8b2f7b0efa8c91067053dd'] = 'Incline le calque le long de l\'axe Y (vertical) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Skews the layer along the Y (vertical) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_b5e0c179725e7f282ffb8e6a96797b49'] = 'ÉchelleX'; // ScaleX
$_MODULE['<{layerslider}prestashop>_15cfa2ea26e51b8489ace013f1b2ec5c'] = 'Met à l\'échelle le calque le long de l\'axe X (horizontal) selon le vecteur spécifié. Utilisez la valeur 1 pour la taille d\'origine. La valeur 2 doublera, tandis que 0,5 réduira le calque par rapport à sa taille d\'origine.'; // Scales the layer along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_3475b72c6483a5c871d245e2567c96c7'] = 'ÉchelleY'; // ScaleY
$_MODULE['<{layerslider}prestashop>_3db72901337b8e6eeaa04ffd8db52e5e'] = 'Met à l\'échelle le calque le long de l\'axe Y (vertical) selon le vecteur spécifié. Utilisez la valeur 1 pour la taille d\'origine. La valeur 2 doublera, tandis que 0,5 réduira le calque par rapport à sa taille d\'origine.'; // Scales the layer along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_e55d5d854ca64aed330e5591b62ae112'] = 'Définit un point sur le canevas à partir duquel les transformations sont calculées. Par exemple, un calque peut pivoter autour de son axe central ou d\'un point entièrement personnalisé, comme l\'un de ses coins. Les trois valeurs représentent les axes X, Y et Z dans l\'espace 3D. Outre les valeurs en pixels et en pourcentage, vous pouvez également utiliser les constantes suivantes : top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.
$_MODULE['<{layerslider}prestashop>_4a18312b5b75f549d5551e5912ad6ebf'] = 'Masque'; // Mask
$_MODULE['<{layerslider}prestashop>_7fb23cb4a33cca7e266b2deda0034711'] = 'Découpe (coupe) les côtés du calque de la quantité spécifiée en pixels ou en pourcentages. Les 4 valeurs dans l\'ordre : haut, droite, bas et côté gauche du calque.'; // Clips (cuts off) the sides of the layer by the given amount specified in pixels or percentages. The 4 value in order: top, right, bottom and the left side of the layer.
$_MODULE['<{layerslider}prestashop>_a9ded1e5ce5d75814730bb4caaf49419'] = 'Arrière-plan'; // Background
$_MODULE['<{layerslider}prestashop>_57315a787bf5df775dcdb38f85aacf7b'] = 'La couleur de fond de votre calque. Vous pouvez utiliser des noms de couleur, des valeurs hexadécimales, RGB ou RGBA ainsi que le mot-clé \'transparent\'. Exemple : #FFF'; // The background color of your layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_cdb3e9cc0b2932a6d1543d19732761f1'] = 'La couleur de votre texte. Vous pouvez utiliser des noms de couleur, des valeurs hexadécimales, RGB ou RGBA. Exemple : #333'; // The color of your text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_cabcfc0f365f0e649cf8c229bf54605e'] = 'Coins arrondis'; // Rounded Corners
$_MODULE['<{layerslider}prestashop>_f0d205bfae354c2e65725ed59bc101e7'] = 'Si vous voulez des coins arrondis, vous pouvez définir leur rayon ici en pixels. Exemple : 5px'; // If you want rounded corners, you can set its radius here in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_32954654ac8fe66a1d09be19001de2d4'] = 'Largeur'; // Width
$_MODULE['<{layerslider}prestashop>_de11d49b6bbf1b1ecd2b424dc1c0c74a'] = 'La largeur initiale de ce calque à partir de laquelle il sera animé à sa taille appropriée pendant la transition.'; // The initial width of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_eec6c4bdbd339edf8cbea68becb85244'] = 'Hauteur'; // Height
$_MODULE['<{layerslider}prestashop>_4cc10791b724542e8a9a04636995d1f5'] = 'La hauteur initiale de ce calque à partir de laquelle il sera animé à sa taille appropriée pendant la transition.'; // The initial height of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_d7778d0c64b6ba21494c97f77a66885a'] = 'Filtre'; // Filter
$_MODULE['<{layerslider}prestashop>_3f6230752680291a660faeec55dc0b73'] = 'Les filtres permettent d\'appliquer des effets comme le flou ou le changement de couleur à vos calques. Cliquez dans le champ de texte pour voir une sélection de filtres que vous pouvez utiliser. Bien que cliquer sur les options prédéfinies réinitialise le champ de texte, vous pouvez appliquer plusieurs filtres simplement en fournissant une liste séparée par des espaces de tous les filtres que vous souhaitez utiliser. Cliquez sur le lien "Filtre" pour plus d\'informations.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use. Click on the "Filter" link for more information.
$_MODULE['<{layerslider}prestashop>_8cb8ac2653a6471f6779aa5c2d9cded2'] = 'Modifie la perspective de ce calque dans l\'espace 3D.'; // Changes the perspective of this layer in the 3D space.
$_MODULE['<{layerslider}prestashop>_cb1fa274044590e8c05e0e3fe44dd203'] = 'Décale le calque de sa position d\'origine sur l\'axe horizontal du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'left\' ou \'right\' animent le calque hors de la zone de préparation, afin qu\'il puisse quitter la scène de chaque côté.'; // Shifts the layer from its original position on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' animate the layer out the staging area, so it can leave the scene on either side.
$_MODULE['<{layerslider}prestashop>_aa243196666cd7d2c5e92dd0f8b9b5f4'] = 'Décale le calque de sa position d\'origine sur l\'axe vertical du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la hauteur de ce calque. Les valeurs \'top\' ou \'bottom\' animent le calque hors de la zone de préparation, afin qu\'il puisse quitter la scène de chaque côté vertical.'; // Shifts the layer from its original position on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' animate the layer out the staging area, so it can leave the scene on either vertical side.
$_MODULE['<{layerslider}prestashop>_f04f3b646758fcab3a12facb6373fdc0'] = 'La durée de la transition en millisecondes lorsque le calque quitte la diapositive. Une seconde équivaut à 1000 millisecondes.'; // The length of the transition in milliseconds when the layer leaves the slide. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_b92bb5e60806c72def5363a5a8bb035e'] = 'Vous pouvez définir l\'heure de début de cette transition. Utilisez l\'une des options prédéfinies pour utiliser une synchronisation relative, qui peut être décalée avec des opérations personnalisées.'; // You can set the starting time of this transition. Use one of the pre-defined options to use relative timing, which can be shifted with custom operations.
$_MODULE['<{layerslider}prestashop>_c36ace66cf4777473ba3200cf815253c'] = 'Le changement de diapositive commence (ignorant le modificateur)'; // Slide change starts (ignoring modifier)
$_MODULE['<{layerslider}prestashop>_371b285fa971d884eaebf156db4065c8'] = 'La transition d\'ouverture se termine'; // Opening Transition completes
$_MODULE['<{layerslider}prestashop>_8920002666c88ed85ae80665159154f4'] = 'La transition de texte d\'ouverture commence'; // Opening Text Transition starts
$_MODULE['<{layerslider}prestashop>_284f03773b79e8472a3798c95c4b9f63'] = 'La transition de texte d\'ouverture se termine'; // Opening Text Transition completes
