$_MODULE['<{layerslider}prestashop>_dc08824d508252f7973060a086788ec1'] = 'Les transitions d\'ouverture, de texte d\'ouverture et de boucle sont terminées'; // Opening, Opening Text and Loop Transitions complete
$_MODULE['<{layerslider}prestashop>_1fcb9ccb4471ff55ac855fcb38bd015b'] = 'La transition de texte de fin commence'; // Ending Text Transition starts
