$_MODULE['<{layerslider}prestashop>_7094fc088dddef6adaa665620fe96dcc'] = 'Incline le calque le long de l\'axe X (horizontal) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Skews the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_049d4369eb664418bd75569e09641c99'] = 'Incline le calque le long de l\'axe Y (vertical) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse.'; // Skews the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_e9e245065a77b7927aaccb2cf9d2ffcd'] = 'Si vous ne voulez pas utiliser ce calque, mais que vous voulez le conserver, vous pouvez le cacher avec ce bouton.'; // If you don't want to use this layer, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_630c4a18856c4ae057355c9398e83a32'] = 'Anime l\'arrière-plan vers la couleur que vous spécifiez ici lorsque le calque quitte la toile du slider.'; // Animates the background toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_77064060d521c47a027e25dab869772f'] = 'Anime la couleur du texte vers la couleur que vous spécifiez ici lorsque le calque quitte la toile du slider.'; // Animates the text color toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_f53e87a23a86051ea35dbfb9f14e6511'] = 'Anime les coins arrondis vers la valeur que vous spécifiez ici lorsque le calque quitte la toile du slider.'; // Animates rounded corners toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_493d9e9e60d44f987c62cd0201269cb5'] = 'Anime la largeur du calque vers la valeur que vous spécifiez ici lorsque le calque quitte la toile du slider.'; // Animates the layer width toward the value you specify here when the layer leaves the slider canvas.
