$_MODULE['<{layerslider}prestashop>_19c45324c9ca36d31215f056839a28c8'] = 'Décalage à l\'entrée'; // Shift In
$_MODULE['<{layerslider}prestashop>_02f41f49726759b91cf468825bdf41a2'] = 'Retarde la transition de chaque nœud de texte les uns par rapport aux autres. Une seconde équivaut à 1000 millisecondes.'; // Delays the transition of each text nodes relative to each other. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_3fff50b68e60ed555ff901b0fdfcd783'] = 'Décale la position de départ des nœuds de texte de leur original sur l\'axe horizontal du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'left\' ou \'right\' positionnent les nœuds de texte hors de la zone de préparation, de sorte qu\'ils entrent en scène de chaque côté lors de l\'animation vers leur emplacement de destination. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Shifts the starting position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they enter the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_e1d2fdcc944aa0f2e839f171f044d659'] = 'Décale la position de départ des nœuds de texte de leur original sur l\'axe vertical du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'top\' ou \'bottom\' positionnent les nœuds de texte hors de la zone de préparation, de sorte qu\'ils entrent en scène de chaque côté vertical lors de l\'animation vers leur emplacement de destination. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Shifts the starting position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they enter the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_968c58d8f1922a6b84d393c59a64a49c'] = 'La durée de la transition en millisecondes des fragments de texte individuels. Une seconde équivaut à 1000 millisecondes.'; // The transition length in milliseconds of the individual text fragments. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_ca6c773be9bea589e35cd5932032450e'] = 'La fonction de synchronisation de l\'animation. Avec cette fonction, vous pouvez manipuler le mouvement des fragments de texte animés. Veuillez cliquer sur le lien à côté de ce champ de sélection pour ouvrir easings.net pour plus d\'informations et des exemples en temps réel.'; // The timing function of the animation. With this function you can manipulate the movement of animated text fragments. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_218ff9f345230b14660e70e66162823f'] = 'Faire un fondu des fragments de texte pendant leur transition.'; // Fade the text fragments during their transition.
$_MODULE['<{layerslider}prestashop>_87140560d2ebde43c1ee6bcbca46632b'] = 'CommenceÀ'; // StartAt
$_MODULE['<{layerslider}prestashop>_5ca3eda902c20e71f2b8a9b37d6400e9'] = 'La transition d\'ouverture commence'; // Opening Transition starts
$_MODULE['<{layerslider}prestashop>_fff3063495dd33cf3909fa4b1a9bc98d'] = 'Fait pivoter les fragments de texte dans le sens des aiguilles d\'une montre du nombre de degrés donné. Les valeurs négatives sont autorisées pour une rotation antihoraire. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Rotates text fragments clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_14f1aa4b97984dfcc375079b84f0eccc'] = 'Fait pivoter les fragments de texte le long de l\'axe X (horizontal) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Rotates text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_871c9bdc8e8606162c54996b7f3e3d55'] = 'Fait pivoter les fragments de texte le long de l\'axe Y (vertical) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Rotates text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_fd776f8e6385f4f4e57c79701beb1f12'] = 'Met à l\'échelle les fragments de texte le long de l\'axe X (horizontal) selon le vecteur spécifié. Utilisez la valeur 1 pour la taille d\'origine. La valeur 2 doublera, tandis que 0,5 réduira les fragments de texte par rapport à leur taille d\'origine. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Scales text fragments along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_b95364eee0d39f1ff08c9511fd007c3b'] = 'Met à l\'échelle les fragments de texte le long de l\'axe Y (vertical) selon le vecteur spécifié. Utilisez la valeur 1 pour la taille d\'origine. La valeur 2 doublera, tandis que 0,5 réduira les fragments de texte par rapport à leur taille d\'origine. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Scales text fragments along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_eec138a9b01bfa45053a9c2e34cc012a'] = 'Incline les fragments de texte le long de l\'axe X (horizontal) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Skews text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_0e34f559e062c73fd9f20e88a6f2dff9'] = 'Incline les fragments de texte le long de l\'axe Y (vertical) du nombre de degrés donné. Les valeurs négatives sont autorisées pour une direction inverse. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Skews text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_5160493a371ec5eaac86b380847e5df5'] = 'Décalage à la sortie'; // Shift Out
$_MODULE['<{layerslider}prestashop>_ef90ee89ac37b9e0f7d58c40106d0489'] = 'Décale la position de fin des nœuds de texte de leur original sur l\'axe horizontal du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'left\' ou \'right\' positionnent les nœuds de texte hors de la zone de préparation, de sorte qu\'ils quittent la scène de chaque côté lors de l\'animation vers leur emplacement de destination. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Shifts the ending position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they leave the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_a7dd960d399567a046b0614242132a75'] = 'Décale la position de fin des nœuds de texte de leur original sur l\'axe vertical du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'top\' ou \'bottom\' positionnent les nœuds de texte hors de la zone de préparation, de sorte qu\'ils quittent la scène de chaque côté vertical lors de l\'animation vers leur emplacement de destination. En listant plusieurs valeurs séparées par un caractère |, le slider utilisera différentes variations de transition sur chaque nœud de texte en cyclant entre les valeurs fournies.'; // Shifts the ending position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they leave the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_d3dd82ed2edaeee8b285d11df248cc2e'] = 'Décale la position de départ du calque de son original sur l\'axe horizontal du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. Les valeurs \'left\' ou \'right\' positionnent le calque hors de la zone de préparation, de sorte qu\'il puisse quitter et ré-entrer en scène de chaque côté pendant la transition.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it can leave and re-enter the scene from either side during the transition.
$_MODULE['<{layerslider}prestashop>_ad02c3d94f8b3590b135be78e2f8e69f'] = 'Décale la position de départ du calque de son original sur l\'axe vertical du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la hauteur de ce calque. Les valeurs \'top\' ou \'bottom\' positionnent le calque hors de la zone de préparation, de sorte qu\'il puisse quitter et ré-entrer en scène de chaque côté vertical pendant la transition.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it can leave and re-enter the scene from either vertical side during the transition.
$_MODULE['<{layerslider}prestashop>_7c1780aa74c2a852b5de424e51739b08'] = 'La durée de la transition en millisecondes. Une seconde équivaut à 1000 millisecondes.'; // The length of the transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_c405823ea6eef48b12c76d719743050e'] = 'La fonction de synchronisation de l\'animation pour manipuler le mouvement du calque. Cliquez sur le lien à côté de ce champ pour ouvrir easings.net pour des exemples et plus d\'informations.'; // The timing function of the animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_bad6a5dd8c28e6b14f8e986615e3dc98'] = 'Opacité'; // Opacity
$_MODULE['<{layerslider}prestashop>_52d096db2d41c73e647fc7b4afe9f4fb'] = 'Fait un fondu du calque. Vous pouvez utiliser des valeurs entre 1 et 0 pour rendre le calque totalement opaque ou transparent respectivement. Par exemple, la valeur 0,5 rendra le calque semi-transparent.'; // Fades the layer. You can use values between 1 and 0 to set the layer fully opaque or transparent respectively. For example, the value 0.5 will make the layer semi-transparent.
$_MODULE['<{layerslider}prestashop>_e93f994f01c537c4e2f7d8528c3eb5e9'] = 'Nombre'; // Count
$_MODULE['<{layerslider}prestashop>_dc9335e13408a714d8e29bf6e5b4af65'] = 'Le nombre de répétitions de la transition en boucle. Le compte inclut la partie inverse des transitions lorsque vous utilisez la fonction Yoyo. Utilisez la valeur -1 pour répéter à l\'infini ou zéro pour désactiver la boucle.'; // The number of times repeating the Loop transition. The count includes the reverse part of the transitions when you use the Yoyo feature. Use the value -1 to repeat infinitely or zero to disable looping.
$_MODULE['<{layerslider}prestashop>_0f68101772bd5397ef8eb1b632798652'] = 'Attente'; // Wait
$_MODULE['<{layerslider}prestashop>_a2dd61cfcfc0bbdf8e5d0bacf03a4bfe'] = 'Temps d\'attente entre les répétitions en millisecondes. Une seconde équivaut à 1000 millisecondes.'; // Waiting time between repeats in milliseconds. A second is 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_7eebb65ba3f2d0b0d5ca4135a1291800'] = 'Yoyo'; // Yoyo
$_MODULE['<{layerslider}prestashop>_d2157b3302d4ec2fb08023a69d4568fd'] = 'Activez cette option pour autoriser la transition inverse, afin de pouvoir boucler en avant et en arrière de manière fluide.'; // Enable this option to allow reverse transition, so you can loop back and forth seamlessly.
$_MODULE['<{layerslider}prestashop>_0211cac74bd72aaae2f7886b1cbde16f'] = 'Déplace le calque horizontalement du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. '; // Moves the layer horizontally by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_780daa5a10788add2c24feda0a7046c9'] = 'Déplace le calque verticalement du nombre de pixels donné. Utilisez des valeurs négatives pour la direction opposée. Les valeurs en pourcentage sont relatives à la largeur de ce calque. '; // Moves the layer vertically by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_70f03c22e8756d36e8ebebf24fc83e68'] = 'Durée<br>inverse'; // Reverse<br>duration
$_MODULE['<{layerslider}prestashop>_f611f13e9d52fe21bddfa2b3c9c6e90a'] = 'La durée de la transition inverse en millisecondes. Une seconde équivaut à 1000 millisecondes.'; // The duration of the reverse transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_36883b3adac19e03ce6e8258a16fbd87'] = 'Accélération<br>inverse'; // Reverse<br>easing
$_MODULE['<{layerslider}prestashop>_0e95be22e52ba91b2a4eac69dea794c6'] = 'La fonction de synchronisation de l\'animation inverse pour manipuler le mouvement du calque. Cliquez sur le lien à côté de ce champ pour ouvrir easings.net pour des exemples et plus d\'informations.'; // The timing function of the reverse animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_18520e0c41ef4863b7c3d57b41e13dd2'] = 'Fait pivoter le calque dans le sens des aiguilles d\'une montre du nombre de degrés donné. Les valeurs négatives sont autorisées pour une rotation antihoraire.'; // Rotates the layer clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_178d558f0ec11adc7f14494caafecfa4'] = 'La couleur de fond de ce calque. Vous pouvez utiliser des noms de couleur, des valeurs hexadécimales, RGB ou RGBA ainsi que le mot-clé \'transparent\'. Exemple : #FFF'; // The background color of this layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_7ccb130b01ecf6f307e49d85d78101ae'] = 'La couleur de ce texte. Vous pouvez utiliser des noms de couleur, des valeurs hexadécimales, RGB ou RGBA. Exemple : #333'; // The text color of this text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_22b4e7bf3118d625243554505037c3d4'] = 'Coins arrondis'; // Rounded corners
$_MODULE['<{layerslider}prestashop>_8baecbc8f47d34ba6f2c94c840039b5d'] = 'Si vous voulez des coins arrondis, vous pouvez définir ici leur rayon en pixels. Exemple : 5px'; // If you want rounded corners, you can set here its radius in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_91b9f1c422bb9c80c97c1409c449b01a'] = 'Modifie la perspective des calques dans l\'espace 3D.'; // Changes the perspective of layers in the 3D space.
$_MODULE['<{layerslider}prestashop>_7b57923badae7705a941c2bb5fdbc259'] = 'Toujours au-dessus'; // Always on top
$_MODULE['<{layerslider}prestashop>_97309a236d6310d21531928e0f237909'] = 'Afficher ce calque au-dessus de tous les autres calques lors du survol.'; // Show this layer above every other layer while hovering.
$_MODULE['<{layerslider}prestashop>_b437c451aa3282f75304078beaccd7f2'] = 'Niveau de parallaxe'; // Parallax Level
$_MODULE['<{layerslider}prestashop>_6d88cda2a17e8c8ba371534044e4dcac'] = 'Définissez l\'intensité de l\'effet de parallaxe. Utilisez des valeurs négatives pour décaler les calques dans la direction opposée.'; // Set the intensity of the parallax effect. Use negative values to shift layers in the opposite direction.
$_MODULE['<{layerslider}prestashop>_e32aeb1f97bbc4b3734bceba06e62189'] = 'Choisissez si vous voulez des calques en parallaxe 2D ou 3D.'; // Choose if you want 2D or 3D parallax layers.
$_MODULE['<{layerslider}prestashop>_db7e7d3165d15f05c446c312cd7ce748'] = 'Hériter des options de la diapositive'; // Inherit from Slide Options
$_MODULE['<{layerslider}prestashop>_65c19dcd436dba37e3f61abaa74fcb0a'] = 'Vous pouvez déclencher l\'effet de parallaxe soit en faisant défiler la page, soit en déplaçant le curseur de votre souris / en inclinant votre appareil mobile.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device.
$_MODULE['<{layerslider}prestashop>_df4937d57d5546a1b7cad8aa01382a30'] = 'Choisissez sur quels axes les calques en parallaxe doivent se déplacer.'; // Choose on which axes parallax layers should move.
$_MODULE['<{layerslider}prestashop>_130c5b3473c57faa76e2a1c54e26f88e'] = 'Les deux'; // Both
$_MODULE['<{layerslider}prestashop>_f8669b1c29bb1d386ed994a5fa3b2383'] = 'Durée du mouvement'; // Move Duration
$_MODULE['<{layerslider}prestashop>_902394e5c2f298dc004991c64ea639e0'] = 'Contrôle la vitesse d\'animation des calques lorsque vous déplacez le curseur de votre souris ou inclinez votre appareil mobile.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device.
$_MODULE['<{layerslider}prestashop>_e6c62193f078181acd6cc60c21353d08'] = 'Durée de sortie'; // Leave Duration
$_MODULE['<{layerslider}prestashop>_387b79d99e6882187a0e3530f37a2f76'] = 'Contrôle la rapidité avec laquelle les calques en parallaxe reviennent à leur position d\'origine lorsque vous déplacez le curseur de votre souris en dehors du slider. Cette valeur est en millisecondes. Une seconde équivaut à 1000 millisecondes.'; // Controls how quickly parallax layers revert to their original position when you move your mouse cursor outside of the slider. This value is in milliseconds. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_64a0612acd329567a634da43b59883cf'] = 'Augmentez ou diminuez la quantité de rotation des calques dans l\'espace 3D lorsque vous déplacez votre curseur de souris ou inclinez un appareil mobile.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_fb86197f4f68b1e2d86783659e7585a3'] = 'Augmentez ou diminuez l\'amplitude du mouvement des calques lorsque vous déplacez votre curseur de souris ou inclinez un appareil mobile.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_7b62b4d0a7de4d976159fb96a6fa6411'] = 'Calque statique'; // Static layer
$_MODULE['<{layerslider}prestashop>_9ae2250c53514362ad6490c3431e5464'] = 'Vous pouvez garder ce calque au-dessus du slider sur plusieurs diapositives. Sélectionnez simplement la diapositive sur laquelle ce calque doit s\'animer en sortie. Alternativement, vous pouvez rendre ce calque global sur toutes les diapositives après son entrée.'; // You can keep this layer on top of the slider across multiple slides. Just select the slide on which this layer should animate out. Alternatively, you can make this layer global on all slides after it transitioned in.
$_MODULE['<{layerslider}prestashop>_9c2690b8a4048048e2c037e4a03339b0'] = 'Désactivé (par défaut)'; // Disabled (default)
$_MODULE['<{layerslider}prestashop>_1d7e5793a0150b3c05de1922cc8c16f5'] = 'Activé (ne s\'anime jamais en sortie)'; // Enabled (never animate out)
$_MODULE['<{layerslider}prestashop>_2a36e79a98871dc76bf33a51af7e3715'] = 'Image clé de la lecture par défilement'; // Play By Scroll Keyframe
$_MODULE['<{layerslider}prestashop>_8e898860158d07998968bfd485788069'] = 'Un slider en lecture par défilement se mettra en pause lorsque ce calque aura terminé sa transition d\'ouverture.'; // A Play by Scroll slider will pause when this layer finished its opening transition.
$_MODULE['<{layerslider}prestashop>_627b4c0e8a9b46747497d4bae491a6c2'] = 'Si vous voulez lier votre calque, tapez ici l\'URL. Vous pouvez utiliser un croisillon suivi d\'un numéro pour lier ce calque à une autre diapositive. Exemple : #3 - cela passera à la troisième diapositive.'; // If you want to link your layer, type here the URL. You can use a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_a33a3e8542755c06996a81a78878b66b'] = 'Cible de l\'URL'; // URL target
$_MODULE['<{layerslider}prestashop>_ba333933886b07c9384523873559a3fd'] = 'Attributs personnalisés'; // Custom Attributes
$_MODULE['<{layerslider}prestashop>_a016d8e10948cfc95215918d4372d8f9'] = 'Votre liste d\'attributs personnalisés. Utilisez cette fonctionnalité si vos besoins ne sont pas couverts par les attributs communs ci-dessus ou si vous souhaitez les remplacer. Vous pouvez utiliser data-* ainsi que des noms d\'attributs réguliers. Les attributs vides (sans valeur) sont également autorisés. Par exemple, pour créer une galerie FancyBox, vous pouvez entrer "data-fancybox-group" et "gallery1" pour le nom et la valeur de l\'attribut, respectivement.'; // Your list of custom attributes. Use this feature if your needs are not covered by the common attributes above or you want to override them. You can use data-* as well as regular attribute names. Empty attributes (without value) are also allowed. For example, to make a FancyBox gallery, you may enter "data-fancybox-group" and "gallery1" for the attribute name and value, respectively.
$_MODULE['<{layerslider}prestashop>_edac8da7d60b7624d4b131bc47a5eb3b'] = 'Vous pouvez définir la largeur de votre calque. Vous pouvez utiliser des pixels, un pourcentage ou la valeur par défaut \'auto\'. Exemples : 100px, 50% ou auto.'; // You can set the width of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto.
$_MODULE['<{layerslider}prestashop>_c6272de402f4e075758f7d27f108d6c1'] = 'Vous pouvez définir la hauteur de votre calque. Vous pouvez utiliser des pixels, un pourcentage ou la valeur par défaut \'auto\'. Exemples : 100px, 50% ou auto'; // You can set the height of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto
$_MODULE['<{layerslider}prestashop>_a4ffdcf0dc1f31b9acaf295d75b51d00'] = 'Haut'; // Top
$_MODULE['<{layerslider}prestashop>_4ce53ede45d38aa6228b7a2e4a9a2d6f'] = 'La position du calque par rapport au haut de la diapositive. Vous pouvez utiliser des pixels et un pourcentage. Exemples : 100px ou 50%. Vous pouvez déplacer vos calques dans l\'aperçu ci-dessus avec un glisser-déposer, ou définir les valeurs exactes ici.'; // The layer position from the top of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_945d5e233cf7d6240f6b783b36a374ff'] = 'Gauche'; // Left
$_MODULE['<{layerslider}prestashop>_38ab4523d162374efdee06dcaa89d7dd'] = 'La position du calque par rapport au côté gauche de la diapositive. Vous pouvez utiliser des pixels et un pourcentage. Exemples : 100px ou 50%. Vous pouvez déplacer vos calques dans l\'aperçu ci-dessus avec un glisser-déposer, ou définir les valeurs exactes ici.'; // The layer position from the left side of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_9bef4210a675b3352481eaba774135e2'] = 'Marge intérieure en haut du calque. Exemple : 10px'; // Padding on the top of the layer. Example: 10px
