$_MODULE['<{layerslider}prestashop>_f8e3211bbd5d1c9e4bbe92fb5006478e'] = 'Style de police'; // Font style
$_MODULE['<{layerslider}prestashop>_935d167268be2e114d55069d55e1a408'] = 'Oblique est une version italique auto-générée de la police que vous avez choisie et peut forcer l\'inclinaison même s\'il n\'y a pas de variante de police italique disponible. Cependant, vous devriez utiliser l\'option italique régulière chaque fois que possible. Veuillez vérifier de charger les variantes de police italique lors de l\'utilisation de Google Fonts.'; // Oblique is an auto-generated italic version of your chosen font and can force slating even if there is no italic font variant available. However, you should use the regular italic option whenever is possible. Please double check to load italic font variants when using Google Fonts.
$_MODULE['<{layerslider}prestashop>_1d874710ccdcd46b95397049d2e7500c'] = 'Italique'; // Italic
$_MODULE['<{layerslider}prestashop>_aa2870bb0730c19998358f5cdbc0dc1b'] = 'Oblique (Inclinaison forcée)'; // Oblique (Forced slant)
$_MODULE['<{layerslider}prestashop>_1fc25820929d0d57c6556736502549e0'] = 'Décoration du texte'; // Text decoration
$_MODULE['<{layerslider}prestashop>_852721aa5fc738dfedff2945d71da439'] = 'Souligné'; // Underline
