$_MODULE['<{layerslider}prestashop>_6d40b0cbf0593b752ece63f7a9928eef'] = 'Contrôle l\'espace entre chaque caractère. Utile pour changer la densité des lettres dans une ligne ou un bloc de texte. Des valeurs négatives et des décimales peuvent être utilisées.'; // Controls the amount of space between each character. Useful the change letter density in a line or block of text. Negative values and decimals can be used.
$_MODULE['<{layerslider}prestashop>_c22b28c5c38d219b521e476691bd7158'] = 'Alignement du texte'; // Text align
$_MODULE['<{layerslider}prestashop>_6c982f951a9fa0736c853e9353ff1553'] = 'Initial (par défaut de la langue)'; // Initial (Language default)
$_MODULE['<{layerslider}prestashop>_4f1f6016fc9f3f2353c0cc7c67b292bd'] = 'Centré'; // Center
$_MODULE['<{layerslider}prestashop>_4b425d212a2e7b36c38703bfdcd57823'] = 'Justifié'; // Justify
$_MODULE['<{layerslider}prestashop>_a8bc50a5bb0ee94aef28600eeccfaa60'] = 'Taille de police min.'; // Min. font size
$_MODULE['<{layerslider}prestashop>_cd7ab6145e3bf89a25e376abd17ab01e'] = 'La taille de police minimale dans un slider responsive. Cette option vous permet d\'éviter que vos calques de texte ne deviennent trop petits sur des écrans plus petits.'; // The minimum font size in a responsive slider. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_e0bc0f8bfc07dfaa60de8a19a075ecaf'] = 'Taille de police min. mobile'; // Min. mobile font size
$_MODULE['<{layerslider}prestashop>_56cac8df2a819eb309f656bec767e641'] = 'La taille de police minimale dans un slider responsive sur les appareils mobiles. Cette option vous permet d\'éviter que vos calques de texte ne deviennent trop petits sur des écrans plus petits.'; // The minimum font size in a responsive slider on mobile devices. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_ee0b6a872572cc985f1d5d20a5901ffb'] = 'Si vous voulez des coins arrondis, vous pouvez définir leur rayon ici. Exemple : 5px'; // If you want rounded corners, you can set its radius here. Example: 5px
$_MODULE['<{layerslider}prestashop>_856ba67470300f8246b140de9a27555d'] = 'Styles personnalisés'; // Custom styles
$_MODULE['<{layerslider}prestashop>_7e045337d227fc13f0b7efdadf341169'] = 'Si vous voulez définir des paramètres de style autres que ceux ci-dessus, vous pouvez utiliser ici n\'importe quel code CSS. Assurez-vous d\'écrire un balisage valide.'; // If you want to set style settings other than above, you can use here any CSS codes. Please make sure to write valid markup.
$_MODULE['<{layerslider}prestashop>_3dbe275d40b3a2b680bdfa25242cc8fe'] = 'L\'angle de rotation vers lequel ce calque s\'anime en entrant dans la toile du slider. Les valeurs négatives sont autorisées pour une rotation antihoraire.'; // The rotation angle where this layer animates toward when entering into the slider canvas. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_fe75b60943091f007ae820a3188868a2'] = 'L\'angle de rotation sur l\'axe horizontal vers lequel il s\'anime en entrant dans la toile du slider. Les valeurs négatives sont autorisées pour une direction inversée.'; // The rotation angle on the horizontal axis where this animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_0c6a5ad5f832c1f79c4b4d62fee16e26'] = 'L\'angle de rotation sur l\'axe vertical vers lequel ce calque s\'anime en entrant dans la toile du slider. Les valeurs négatives sont autorisées pour une direction inversée.'; // The rotation angle on the vertical axis where this layer animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_6af83f149c018cdec1dba351c619b7ca'] = 'L\'échelle horizontale du calque vers laquelle ce calque s\'anime en entrant dans la toile du slider.'; // The layer horizontal scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_28d8b2ec189dc2eb778a851265cf4f26'] = 'L\'échelle verticale du calque vers laquelle ce calque s\'anime en entrant dans la toile du slider.'; // The layer vertical scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_63d48e08093f6964b3cdc6d33740663e'] = 'L\'angle d\'inclinaison horizontal du calque vers lequel ce calque s\'anime en entrant dans la toile du slider.'; // The layer horizontal skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_e4b23d4080824b973029720a307cbae6'] = 'L\'angle d\'inclinaison vertical du calque vers lequel ce calque s\'anime en entrant dans la toile du slider.'; // The layer vertical skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_45f908bb74a7835d23630c7d51031fed'] = 'Calculer les positions à partir de'; // Calculate positions from
$_MODULE['<{layerslider}prestashop>_639b76980c25ea95700d2c2e96833964'] = 'Définit l\'origine de la position du calque à partir de laquelle les valeurs de haut et de gauche sont calculées. La valeur par défaut est le coin supérieur gauche de la toile du slider. Dans un slider pleine largeur et pleine taille, votre contenu est centré en fonction de la taille de l\'écran pour obtenir le meilleur ajustement possible. En sélectionnant l\'option "côtés de l\'écran" dans ces scénarios, vous pouvez permettre aux calques d\'échapper à la zone intérieure centrée et de coller aux côtés de l\'écran.'; // Sets the layer position origin from which top and left values are calculated. The default is the upper left corner of the slider canvas. In a full width and full size slider, your content is centered based on the screen size to achieve the best possible fit. By selecting the "sides of the screen" option in those scenarios, you can allow layers to escape the centered inner area and stick to the sides of the screen.
$_MODULE['<{layerslider}prestashop>_b16710c8d62abca1ccda544c63bea7e8'] = 'côtés du slider'; // sides of the slider
$_MODULE['<{layerslider}prestashop>_ab761fc53dc83dca5a36b9a25bf548bf'] = 'côtés de l\'écran'; // sides of the screen
$_MODULE['<{layerslider}prestashop>_51400b417ad07f539ecfd9469027a5b6'] = 'Ordre d\'empilement'; // Stacking order
$_MODULE['<{layerslider}prestashop>_4c26a68fa7463987e86f61733caf8491'] = 'Cette option contrôle l\'ordre d\'empilement vertical des calques qui se chevauchent. En CSS, on l\'appelle communément z-index. Les éléments avec une valeur plus élevée sont empilés devant les éléments avec une valeur plus basse, les couvrant efficacement. Par défaut, cette valeur est calculée automatiquement en fonction de l\'ordre de vos calques, donc un simple ré-ordonnancement peut résoudre les problèmes de chevauchement. Utilisez cette option uniquement si vous voulez définir votre propre valeur manuellement dans des cas spéciaux comme l\'utilisation de calques statiques.<br><br>Sur chaque diapositive, l\'ordre d\'empilement commence à compter à partir de 100. Fournir un nombre inférieur à 100 mettra le calque derrière tous les autres calques sur toutes les diapositives. Spécifier un nombre beaucoup plus grand, par exemple 500, fera en sorte que le calque soit au-dessus de tout le reste.'; // This option controls the vertical stacking order of layers that overlap. In CSS, it's commonly called as z-index. Elements with a higher value are stacked in front of elements with a lower one, effectively covering them. By default, this value is calculated automatically based on the order of your layers, thus simply re-ordering them can fix overlap issues. Use this option only if you want to set your own value manually in special cases like using static layers.<br><br>On each slide, the stacking order starts counting from 100. Providing a number less than 100 will put the layer behind every other layer on all slides. Specifying a much greater number, for example 500, will make the layer to be on top of everything else.
$_MODULE['<{layerslider}prestashop>_0c301043ef92f5854d711e54f96a86c5'] = 'Mode de fusion'; // Blend mode
$_MODULE['<{layerslider}prestashop>_df5c4d0c2cd9156afa20fa59c572acde'] = 'Choisissez comment les calques et l\'arrière-plan de la diapositive doivent se fondre les uns dans les autres. Les modes de fusion sont un moyen facile d\'ajouter des effets accrocheurs et sont l\'une des fonctionnalités les plus fréquemment utilisées en conception graphique et imprimée.'; // Choose how layers and the slide background should blend into each other. Blend modes are an easy way to add eye-catching effects and is one of the most frequently used features in graphic and print design.
$_MODULE['<{layerslider}prestashop>_b718adec73e04ce3ec720dd11a06a308'] = 'ID'; // ID
$_MODULE['<{layerslider}prestashop>_ca79528715d6c07cb429e8189105cbb4'] = 'Vous pouvez appliquer un attribut ID à l\'élément HTML de ce calque pour l\'utiliser dans votre code CSS ou Javascript personnalisé.'; // You can apply an ID attribute on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_e9878b4854d29907146149f695cb1cfb'] = 'Classes'; // Classes
$_MODULE['<{layerslider}prestashop>_c666f7b19a598af3cadb8c9cb07c4bcd'] = 'Vous pouvez appliquer des classes à l\'élément HTML de ce calque pour l\'utiliser dans votre code CSS ou Javascript personnalisé.'; // You can apply classes on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_3ace045d5becea8953aabde365c5c8d8'] = 'Vous pouvez ajouter un titre à ce calque qui s\'affichera comme une infobulle si quelqu\'un maintient le curseur de sa souris sur le calque.'; // You can add a title to this layer which will display as a tooltip if someone holds his mouse cursor over the layer.
$_MODULE['<{layerslider}prestashop>_f2364c335fe8ae15c8d64b2744db0f40'] = 'Nommez ou décrivez votre calque d\'image, afin que les moteurs de recherche et les logiciels de lecture d\'écran puissent l\'identifier correctement.'; // Name or describe your image layer, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_eba991d56b1be0b940d722211bab87bc'] = 'Rel'; // Rel
$_MODULE['<{layerslider}prestashop>_b987cf5b1aa6af2a92b97f69d65c29df'] = 'Les plugins et les moteurs de recherche peuvent utiliser cet attribut pour obtenir plus d\'informations sur le rôle et le comportement d\'un lien.'; // Plugins and search engines may use this attribute to get more information about the role and behavior of a link.
$_MODULE['<{layerslider}prestashop>_5d083603a18046659c2b4b23af7948cc'] = 'Option avancée'; // Advanced option
$_MODULE['<{layerslider}prestashop>_31fde7b05ac8952dacf4af8a704074ec'] = 'Aperçu'; // Preview
$_MODULE['<{layerslider}prestashop>_a67f2c9d056f29b94521c17b838b9756'] = 'Tuiles'; // Tiles
$_MODULE['<{layerslider}prestashop>_530f488f7a9800411efc6926ab189708'] = 'Lignes'; // Rows
$_MODULE['<{layerslider}prestashop>_35b93b52adc0893d6f4b32752660535f'] = '<i>nombre</i> ou <i>min,max</i> Si vous spécifiez une valeur supérieure à 1, Creative Slider coupera votre diapositive en tuiles. Vous pouvez spécifier ici combien de lignes votre transition doit avoir. Si vous spécifiez deux nombres séparés par une virgule, Creative Slider l\'utilisera comme une plage et choisira un nombre aléatoire entre vos valeurs.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many rows of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_d27561f45c58f407b3fe76b63b1ec28a'] = 'Cols'; // Cols
$_MODULE['<{layerslider}prestashop>_a122bf49cbf8c9cf02971a495e81ed16'] = '<i>nombre</i> ou <i>min,max</i> Si vous spécifiez une valeur supérieure à 1, Creative Slider coupera votre diapositive en tuiles. Vous pouvez spécifier ici combien de colonnes votre transition doit avoir. Si vous spécifiez deux nombres séparés par une virgule, Creative Slider l\'utilisera comme une plage et choisira un nombre aléatoire entre vos valeurs.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many columns of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_8f497c1a3d15af9e0c215019f26b887d'] = 'Délai'; // Delay
$_MODULE['<{layerslider}prestashop>_d4f0208d1a34d7a381fc8abec990105b'] = 'Vous pouvez appliquer un délai entre les tuiles et reporter leur animation les unes par rapport aux autres.'; // You can apply a delay between the tiles and postpone their animation relative to each other.
$_MODULE['<{layerslider}prestashop>_3ff39d3acb327553070a64ef0cb321d5'] = 'Séquence'; // Sequence
$_MODULE['<{layerslider}prestashop>_434cd8b268e79b39af562cc6329d56fb'] = 'Vous pouvez contrôler l\'ordre d\'animation des tuiles ici.'; // You can control the animation order of the tiles here.
$_MODULE['<{layerslider}prestashop>_67d2f6740a8eaebf4d5c6f79be8da481'] = 'Avant'; // Forward
$_MODULE['<{layerslider}prestashop>_67f115c1fddc4ce1aeb1c754001585bc'] = 'Inverse'; // Reverse
$_MODULE['<{layerslider}prestashop>_13db785ec723ba5b44f1a1311edc9332'] = 'Col-avant'; // Col-forward
$_MODULE['<{layerslider}prestashop>_3898dd1cf4144fda9dfac68e6c3b7c41'] = 'Col-inverse'; // Col-reverse
$_MODULE['<{layerslider}prestashop>_afedf9afee367f51f98d7cf030c976a6'] = 'Transition'; // Transition
$_MODULE['<{layerslider}prestashop>_1f3b894b65d30b6d1f137f4b4dad7823'] = 'La durée de l\'animation. Cette valeur est en millisecondes, donc la valeur 1000 signifie 1 seconde.'; // The duration of the animation. This value is in millisecs, so the value 1000 measn 1 second.
$_MODULE['<{layerslider}prestashop>_639a36a8fd5673fccfa75e572ca859f7'] = 'Le type d\'animation, soit glissement, fondu ou les deux (mixte).'; // The type of the animation, either slide, fade or both (mixed).
