$_MODULE['<{layerslider}prestashop>_8cd9b481d7b1dba122421f460aa881d3'] = 'Définit l\'heure de début de cette transition. Sélectionnez l\'une des options prédéfinies dans cette liste pour contrôler la synchronisation par rapport à d\'autres types de transition. De plus, vous pouvez décaler l\'heure de début avec les contrôles de modificateur ci-dessous.'; // Sets the starting time for this transition. Select one of the pre-defined options from this list to control timing in relation with other transition types. Additionally, you can shift starting time with the modifier controls below.
$_MODULE['<{layerslider}prestashop>_9a58721d33e670fce7361aa9e3d9ff70'] = 'Commence quand'; // Start when
$_MODULE['<{layerslider}prestashop>_4d08efe2791a677104f296ad0a66b05b'] = 'Décale l\'heure de début sélectionnée ci-dessus en effectuant une opération personnalisée. Par exemple, &quot;- 1000&quot; avancera l\'animation en la jouant 1 seconde (1000 millisecondes) plus tôt.'; // Shifts the above selected starting time by performing a custom operation. For example, &quot;- 1000&quot; will advance the animation by playing it 1 second (1000 milliseconds) earlier.
$_MODULE['<{layerslider}prestashop>_e755893aa10c3a8f08d2bc2fad9f3d0a'] = 'avec modificateur'; // with modifier
$_MODULE['<{layerslider}prestashop>_3e1fcbcdc912d9ac76af9202b8ee1e40'] = 'Propriétés de la transition en boucle / intermédiaire'; // Loop / Middle Transition properties
$_MODULE['<{layerslider}prestashop>_fb1eb0bc378ca1a36b8f1af434973cdb'] = 'Répète une transition en fonction des options ci-dessous. Si vous définissez le nombre de boucles sur 1, elle peut également agir comme une transition intermédiaire dans la chaîne des cycles de vie de l\'animation.'; // Repeats a transition based on the options below. If you set the Loop Count to 1, it can also act as a middle transition in the chain of animation lifecycles.
$_MODULE['<{layerslider}prestashop>_a9aad76491b11de0946f522d395fddc6'] = 'Chaque fragment de texte s\'animera à partir du mot entier joint vers les options que vous spécifiez ici.'; // Each text fragment will animate from the joint whole word to the options you specify here.
