$_MODULE['<{layerslider}prestashop>_7fac79313672181ae061efda7f2bad21'] = 'Attributs communs'; // Common Attributes
$_MODULE['<{layerslider}prestashop>_c6c4aad8baab7c6136347bdee1753f6c'] = 'Dans certains cas, vos calques peuvent être enveloppés par un autre élément. Par exemple, une balise ＜A＞ lorsque vous utilisez la liaison de calque. Certains attributs seront appliqués à l\'enveloppe (le cas échéant), ce qui est souhaitable dans de nombreux cas (par exemple, les plugins de lightbox). S\'il n\'y a pas d\'élément d\'enveloppe, les attributs seront automatiquement appliqués au calque lui-même. Si l\'option prédéfinie ne correspond pas à vos besoins, utilisez des attributs personnalisés ci-dessous pour la remplacer.'; // In some cases your layers may be wrapped by another element. For example, an ＜A＞ tag when you use layer linking. Some attributes will be applied on the wrapper (if any), which is desirable in many cases (e.g. lightbox plugins). If there is no wrapper element, attributes will be automatically applied on the layer itself. If the pre-defined option doesn't fit your needs, use custom attributes below to override it.
$_MODULE['<{layerslider}prestashop>_0f70708d6cc70283e9a9af03e3bc413e'] = 'Sur le calque'; // On layer
$_MODULE['<{layerslider}prestashop>_cb8bcaba66921cc105c4c74cafcc45e6'] = 'Sur le parent'; // On parent
