$_MODULE['<{layerslider}prestashop>_04099750838e0b2fc6c9d68c5dc47b42'] = 'Ayez l\'esprit tranquille en sachant que vos modifications de slider sont toujours en sécurité et que vous pouvez annuler les modifications indésirables ou les sauvegardes défectueuses à tout moment. Cette fonctionnalité ne sert pas seulement de solution de sauvegarde, mais aussi de système de contrôle de version complet où vous pouvez comparer visuellement les modifications que vous avez apportées en cours de route.'; // Have a peace of mind knowing that your slider edits are always safe and you can revert back unwanted changes or faulty saves at any time. This feature serves not just as a backup solution, but a complete version control system where you can visually compare the changes you have made along the way.
$_MODULE['<{layerslider}prestashop>_3a06c5ff9c120c2e7e49750f76c3b0c9'] = 'Personnaliser les préférences de révisions'; // Customize Revisions Preferences
