$_MODULE['<{layerslider}prestashop>_85e5569165918988076ed20f567709ab'] = 'Attendre au moins %s minutes entre les modifications avant d\'ajouter une nouvelle révision.'; // Wait at least %s minutes between edits before adding a new revision.
$_MODULE['<{layerslider}prestashop>_a79dc794e7af45729dfba74a532f0ad6'] = 'Les révisions de slider stockent également les contrôles annuler/rétablir. Il n\'y a aucune raison d\'utiliser des sauvegardes très fréquentes puisque vous pourrez annuler les modifications intermédiaires.'; // Slider Revisions also stores the undo/redo controls. There is no reason using very frequent saves since you will be able to undo the changes in-between.
