$_MODULE['<{layerslider}prestashop>_d69de1175ad3d34048bfd72f8c2728ea'] = 'Vous cherchez le contenu de démonstration importable ? Consultez la %sBoutique de modèles%s.'; // Looking for the importable demo content? Check out the %sTemplate Store%s.
$_MODULE['<{layerslider}prestashop>_cc0da7a91d632e541ca11db8e8e77c18'] = 'Avis : Pour importer à partir de versions obsolètes (antérieures à la v3.0.0), vous devez créer un nouveau fichier et y coller le code d\'exportation. Le fichier doit avoir une extension .json, vous pourrez alors le télécharger.'; // Notice: In order to import from outdated versions (pre-v3.0.0), you need to create a new file and paste the export code into it. The file needs to have a .json extension, then you will be able to upload it.
$_MODULE['<{layerslider}prestashop>_d1673e2c8908f8939c5d0ba949ebc80b'] = 'Importer des sliders'; // Import Sliders
$_MODULE['<{layerslider}prestashop>_00a38f6db60b94e13225141261806f19'] = 'Il n\'y a pas encore de révisions disponibles pour le slider sélectionné. Les révisions seront ajoutées au fil du temps lorsque vous apporterez de nouvelles modifications à vos sliders. Vérifiez les %sPréférences des révisions%s et assurez-vous que les révisions sont activées.'; // There are no revisions available for the selected slider yet. Revisions will be added over time when you make new changes to your sliders. Check %sRevisions Preferences%s and make sure that Revisions is enabled.
